<?php
require __DIR__.'/../includes/upb_bj_input_template.php';
function structureCheck($ok,$msg){if(!$ok)throw new RuntimeException($msg);}
function structureRead(string $bytes,?callable $edit=null){$p=tempnam('/tmp','upb-structure-');try{file_put_contents($p,$bytes);$z=new ZipArchive();$z->open($p);$d=upbBjXml($z->getFromName('content.xml'));if(!$edit){$z->close();return $d;}$edit($d);$z->addFromString('content.xml',$d->saveXML());$z->close();return file_get_contents($p);}finally{unlink($p);}}
$fixture=structureRead(buildUpbBjInputTemplateOds('2026-02'),function($d){$tables=upbBjTables($d);$t=$tables['FEBRUARI'];$r=1;foreach(iterator_to_array($t->childNodes) as $row){if(!$row instanceof DOMElement||$row->localName!=='table-row')continue;if($r===8){$product=$d->createElementNS(UPB_T,'table:table-row');$t->insertBefore($product,$row);foreach([3=>'KATEGORI TAMBAHAN',6=>'PRODUK CONTOH BARU'] as $col=>$value){$cell=upbBjColumnCell($product,$col);$cell->appendChild($d->createElementNS(UPB_X,'text:p',$value));}foreach([7=>5,9=>4321] as $col=>$value){$cell=upbBjColumnCell($product,$col);$cell->setAttributeNS(UPB_O,'office:value-type','float');$cell->setAttributeNS(UPB_O,'office:value',(string)$value);$cell->appendChild($d->createElementNS(UPB_X,'text:p',(string)$value));}upbBjSetFormula(upbBjColumnCell($product,10),"['FEBRUARI'.I8]+1",4322);break;}$r+=max(1,(int)$row->getAttributeNS(UPB_T,'number-rows-repeated'));}});
$fixture=structureRead($fixture,function($d){$t=upbBjTables($d)['FEBRUARI'];foreach($t->getElementsByTagNameNS(UPB_T,'table-cell') as $cell)if($cell->hasAttributeNS(UPB_T,'formula'))$cell->setAttributeNS(UPB_T,'table:formula',$cell->getAttributeNS(UPB_T,'formula').'+0');});
$source=upbBjTables(structureRead($fixture))['FEBRUARI'];$result=upbBjTables(structureRead(buildUpbBjInputTemplateOds('2026-04',$fixture)));
foreach(['MARET','APRIL'] as $name){$table=$result[$name];$cells=upbBjCells($table);structureCheck(!str_contains($table->textContent,'PRODUK CONTOH BARU'),'New product name left empty');structureCheck(!str_contains($table->textContent,'KATEGORI TAMBAHAN'),'New category input left empty');foreach(range(2,8) as $column)if(isset($cells[8][$column]))structureCheck(trim($cells[8][$column]->textContent)==='','New month product inputs blank');structureCheck($table->getElementsByTagNameNS(UPB_T,'table-row')->length===$source->getElementsByTagNameNS(UPB_T,'table-row')->length,'Row structure copied');structureCheck(!isset($cells[8][7])||!$cells[8][7]->hasAttributeNS(UPB_O,'value'),'Quantity blank');structureCheck(!isset($cells[8][9])||!$cells[8][9]->hasAttributeNS(UPB_O,'value'),'Amount blank');structureCheck($cells[8][10]->getAttributeNS(UPB_T,'formula')==="of:=['".$name."'.I8]+1+0",'Formula copied and own-sheet reference updated');structureCheck(upbBjBottom($table)['FARMASI']['value']===0.0,'New month cumulative starts empty');$originalCells=upbBjCells($source);foreach($originalCells as $r=>$row)foreach([7,9] as $col)if(isset($row[$col])&&$row[$col]->hasAttributeNS(UPB_T,'formula'))structureCheck($cells[$r][$col]->getAttributeNS(UPB_T,'formula')===$row[$col]->getAttributeNS(UPB_T,'formula'),'User-customized subtotal/bottom formula preserved');}
$old=upbBjCells($result['FEBRUARI']);structureCheck((float)$old[8][9]->getAttributeNS(UPB_O,'value')===4321.0,'Old inputs unchanged');validateUpbBjOds(buildUpbBjInputTemplateOds('2026-04',$fixture),'2026-04');
// A missing/renamed grand-total label must not let product clearing erase the footer.
$broken=structureRead($fixture,function($d){$table=upbBjTables($d)['FEBRUARI'];$bottom=upbBjBottom($table);$positions=[];$r=1;foreach($table->childNodes as $node)if($node instanceof DOMElement&&$node->localName==='table-row'){$positions[$r]=$node;$r+=max(1,(int)$node->getAttributeNS(UPB_T,'number-rows-repeated'));}foreach($bottom as $entry){$r=(int)substr($entry['ref'],1);$cell=upbBjColumnCell($positions[$r],6);while($cell->firstChild)$cell->removeChild($cell->firstChild);}foreach(upbBjCells($table) as $r=>$cells)if(strtoupper(trim($cells[1]->textContent??''))==='TOTAL'){$cell=upbBjColumnCell($positions[$r],1);while($cell->firstChild)$cell->removeChild($cell->firstChild);}});
$fixed=upbBjTables(structureRead(buildUpbBjInputTemplateOds('2026-04',$broken)));foreach(['FEBRUARI','MARET','APRIL'] as $name){$bottom=upbBjBottom($fixed[$name]);foreach(['FARMASI','SOBISCO','CANDY','TOTAL'] as $label)structureCheck(isset($bottom[$label]),'Footer labels restored and retained');}
echo "PASS: next months copy row structure/formulas with blank product/category inputs, refresh self-references, clear amounts/quantities and retain saved inputs.\n";
